import {fields,object,text,integer,email,validation} from '@crew/shared';
import {issueInput,labelInput} from '../../../../shared/src/schemas/issue.js';
import {projectInput,workflowInput} from '../../../../shared/src/schemas/project.js';
import {commentInput,relationInput,relationPair} from '../../../../shared/src/schemas/discussion.js';
import {TRANSFER_FORMAT,TRANSFER_VERSION} from './transfer-export.js';
const documentFields=['format','version','exportedAt','project','statuses','users','externalIssues','labels','issues','comments','relations'];
function fail(field,message){throw validation({[field]:message});}
function at(field,fn) {
  try{return fn();}
  catch(error){if(error.code==='VALIDATION')throw validation(Object.fromEntries(Object.entries(error.details??{}).map(([key,value])=>[field+'.'+key,value])));throw error;}
}
function id(value,field){return text(value,field,{max:128});}
function timestamp(value,field) {
  if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}T/.test(value)||!Number.isFinite(Date.parse(value)))fail(field,'Use an ISO UTC timestamp');
  const normalized=new Date(value).toISOString();
  if(!value.endsWith('Z')||normalized.slice(0,10)!==value.slice(0,10))fail(field,'Use a real UTC calendar timestamp');
  return normalized;
}
function records(value,field,parse) {
  if(!Array.isArray(value))fail(field,'Expected an array');
  const ids=new Set();
  return value.map((input,index)=>at(field+'.'+index,()=>{
    object(input);const record=parse(input,index);record.id=id(input.id,'id');
    if(ids.has(record.id))fail('id','Duplicate identifier');ids.add(record.id);return record;
  }));
}
function times(row){const createdAt=timestamp(row.createdAt,'createdAt'),updatedAt=timestamp(row.updatedAt,'updatedAt');if(updatedAt<createdAt)fail('updatedAt','Must not precede createdAt');return {createdAt,updatedAt};}
function known(value,set,field,{nullable=false}={}) {
  if(nullable&&value===null)return;
  if(!set.has(value))fail(field,'Reference is absent from the export catalog');
}
export function orderIssues(issues) {
  const pending=new Map(issues.map(issue=>[issue.id,issue])),children=new Map(),queue=[];
  for(const issue of issues) {
    if(!issue.parentId)queue.push(issue);
    else {const list=children.get(issue.parentId)??[];list.push(issue);children.set(issue.parentId,list);}
  }
  queue.sort((a,b)=>a.number-b.number);
  const result=[];
  for(let index=0;index<queue.length;index++) {
    const issue=queue[index];result.push(issue);pending.delete(issue.id);
    for(const child of children.get(issue.id)??[])queue.push(child);
  }
  if(pending.size)fail('issues.parentId','Parent references contain a cycle');
  return result;
}
function validateRelations(relations,issueIds,externalIds,userIds) {
  const pairs=new Set(),duplicates=new Set();
  for(const relation of relations) {
    const nodes=new Set([...issueIds,...externalIds]);
    known(relation.sourceIssueId,nodes,'relations.'+relation.id+'.sourceIssueId');
    known(relation.targetIssueId,nodes,'relations.'+relation.id+'.targetIssueId');
    known(relation.createdBy,userIds,'relations.'+relation.id+'.createdBy');
    if(!issueIds.has(relation.sourceIssueId)&&!issueIds.has(relation.targetIssueId))fail('relations.'+relation.id,'At least one endpoint must be an exported issue');
    const [source,target]=relationPair(relation.sourceIssueId,relation.targetIssueId,relation.kind);
    const key=relation.kind+':'+source+':'+target;
    if(pairs.has(key))fail('relations.'+relation.id,'Duplicate relation');pairs.add(key);
    if(relation.kind==='duplicates'){
      if(duplicates.has(source))fail('relations.'+relation.id,'An issue may duplicate only one original');duplicates.add(source);
    }
  }
  for(const kind of ['blocks','duplicates']) {
    const edges=new Map(),degrees=new Map();
    for(const relation of relations.filter(row=>row.kind===kind)){
      const list=edges.get(relation.sourceIssueId)??[];list.push(relation.targetIssueId);edges.set(relation.sourceIssueId,list);
      degrees.set(relation.sourceIssueId,degrees.get(relation.sourceIssueId)??0);
      degrees.set(relation.targetIssueId,(degrees.get(relation.targetIssueId)??0)+1);
    }
    const queue=[...degrees].filter(([,count])=>count===0).map(([id])=>id);let visited=0;
    for(let index=0;index<queue.length;index++){visited++;for(const target of edges.get(queue[index])??[]){degrees.set(target,degrees.get(target)-1);if(!degrees.get(target))queue.push(target);}}
    if(visited!==degrees.size)fail('relations','The '+kind+' graph contains a cycle');
  }
}
export function validateDocument(input) {
  fields(input,documentFields);
  if(input.format!==TRANSFER_FORMAT||input.version!==TRANSFER_VERSION)fail('document','Expected a Crew project export version '+TRANSFER_VERSION);
  timestamp(input.exportedAt,'exportedAt');fields(input.project,['id','key','name','description']);id(input.project.id,'project.id');
  const project=at('project',()=>projectInput({key:input.project.key,name:input.project.name,description:input.project.description}));
  const statuses=records(input.statuses,'statuses',(row,index)=>{
    fields(row,['id','name','category','position']);integer(row.position,'position',{min:0});
    if(row.position!==index)fail('position','Statuses must be ordered by consecutive position');
    return {id:row.id,name:row.name,category:row.category,position:index};
  });
  at('statuses',()=>workflowInput({statuses:statuses.map(({id,name,category})=>({id,name,category}))}));
  const users=records(input.users,'users',row=>{fields(row,['id','name','email']);return {name:text(row.name,'name',{max:120}),email:email(row.email)};});
  const labels=records(input.labels,'labels',row=>{fields(row,['id','name','color','createdAt','updatedAt']);return {...labelInput({name:row.name,color:row.color}),...times(row)};});
  const names=new Set();for(const label of labels){const name=label.name.toLowerCase();if(names.has(name))fail('labels','Label names must be unique');names.add(name);}
  const issues=records(input.issues,'issues',row=>{
    fields(row,['id','number','title','description','statusId','priority','assigneeId','estimate','dueDate','parentId','createdBy','rank','labelIds','createdAt','updatedAt']);
    const value=issueInput(Object.fromEntries(['title','description','statusId','priority','assigneeId','estimate','dueDate','parentId','labelIds'].map(key=>[key,row[key]])));
    if(!Number.isFinite(row.rank))fail('rank','Expected a finite board rank');
    return {...value,number:integer(row.number,'number',{min:1,max:1000000000}),createdBy:id(row.createdBy,'createdBy'),rank:row.rank,...times(row)};
  });
  const externalIssues=records(input.externalIssues??[],'externalIssues',row=>{
    fields(row,['id','key','title','projectId']);return {key:text(row.key,'key',{max:128}),title:text(row.title,'title',{max:300}),projectId:id(row.projectId,'projectId')};
  });
  const issueIds=new Set(issues.map(row=>row.id)),statusIds=new Set(statuses.map(row=>row.id)),labelIds=new Set(labels.map(row=>row.id)),userIds=new Set(users.map(row=>row.id)),externalIds=new Set(externalIssues.map(row=>row.id));
  for(const externalId of externalIds)if(issueIds.has(externalId))fail('externalIssues','External and included issue IDs must be disjoint');
  const numbers=new Set();
  for(const issue of issues) {
    if(numbers.has(issue.number))fail('issues.'+issue.id+'.number','Duplicate issue number');numbers.add(issue.number);
    known(issue.statusId,statusIds,'issues.'+issue.id+'.statusId');
    known(issue.createdBy,userIds,'issues.'+issue.id+'.createdBy');
    known(issue.assigneeId,userIds,'issues.'+issue.id+'.assigneeId',{nullable:true});
    known(issue.parentId,issueIds,'issues.'+issue.id+'.parentId',{nullable:true});
    for(const labelId of issue.labelIds)known(labelId,labelIds,'issues.'+issue.id+'.labelIds');
  }
  orderIssues(issues);
  const comments=records(input.comments,'comments',row=>{
    fields(row,['id','issueId','authorId','body','createdAt','updatedAt']);
    const value=commentInput({body:row.body});if(!value.body.trim())fail('body','Comments cannot be blank');
    known(row.issueId,issueIds,'issueId');known(row.authorId,userIds,'authorId');
    return {...value,issueId:row.issueId,authorId:row.authorId,...times(row)};
  });
  const relations=records(input.relations,'relations',row=>{
    fields(row,['id','sourceIssueId','targetIssueId','kind','createdBy','createdAt']);
    relationInput({targetIssueId:row.targetIssueId,kind:row.kind});
    return {sourceIssueId:id(row.sourceIssueId,'sourceIssueId'),targetIssueId:row.targetIssueId,kind:row.kind,createdBy:row.createdBy,createdAt:timestamp(row.createdAt,'createdAt')};
  });
  validateRelations(relations,issueIds,externalIds,userIds);
  return {project,statuses,users,labels,issues,comments,relations,externalIssues};
}
export function importPlan(ctx,req,orgId,body) {
  fields(body,['document','key','name','userMap','externalIssueMap','preview']);
  ctx.permissions.assertOrg(req,orgId,'import:write');ctx.permissions.assertOrg(req,orgId,'project:manage');
  ctx.permissions.scope(req,'issue:write');ctx.permissions.scope(req,'comment:write');
  if(body.preview!==undefined&&typeof body.preview!=='boolean')fail('preview','Expected true or false');
  const document=at('document',()=>validateDocument(body.document));
  const project=projectInput({key:body.key??document.project.key,name:body.name??document.project.name,description:document.project.description});
  if(ctx.db.prepare('SELECT 1 FROM projects WHERE org_id=? AND key=?').get(orgId,project.key))fail('key','A project with this key already exists');
  const requestedUsers=object(body.userMap??{}),requestedExternal=object(body.externalIssueMap??{});
  const userMap=new Map(),externalIssueMap=new Map(),errors={};
  for(const key of Object.keys(requestedUsers))if(!document.users.some(user=>user.id===key))errors['userMap.'+key]='Unknown exported user';
  for(const user of document.users) {
    const explicit=Object.hasOwn(requestedUsers,user.id);
    const targetId=explicit?requestedUsers[user.id]:ctx.db.prepare('SELECT u.id FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.org_id=? AND u.email=?').get(orgId,user.email)?.id;
    const member=typeof targetId==='string'?ctx.permissions.membership(targetId,orgId):null;
    if(!member||member.role==='guest')errors['userMap.'+user.id]='Map '+user.email+' to a non-guest member of the destination organization';
    else userMap.set(user.id,targetId);
  }
  for(const key of Object.keys(requestedExternal))if(!document.externalIssues.some(issue=>issue.id===key))errors['externalIssueMap.'+key]='Unknown exported external issue';
  for(const issue of document.externalIssues) {
    const targetId=requestedExternal[issue.id];
    const target=typeof targetId==='string'?ctx.db.prepare('SELECT i.id,i.project_id,p.org_id FROM issues i JOIN projects p ON p.id=i.project_id WHERE i.id=?').get(targetId):null;
    if(!target||target.org_id!==orgId||!ctx.permissions.canProject(req.user.id,target.project_id,'issue:write'))errors['externalIssueMap.'+issue.id]='Explicitly map '+issue.key+' to a writable issue in this organization';
    else externalIssueMap.set(issue.id,target.id);
  }
  if(Object.keys(errors).length)throw validation(errors,'Resolve the import identity mappings');
  return {document,project,userMap,externalIssueMap,summary:{project,counts:{issues:document.issues.length,comments:document.comments.length,labels:document.labels.length,relations:document.relations.length,statuses:document.statuses.length},
    users:document.users.map(user=>({...user,targetId:userMap.get(user.id),target:ctx.db.prepare('SELECT id,name,email FROM users WHERE id=?').get(userMap.get(user.id))})),externalIssues:document.externalIssues.map(issue=>({...issue,targetId:externalIssueMap.get(issue.id),target:ctx.db.prepare("SELECT i.id,p.key||'-'||i.number AS key,i.title,i.project_id AS projectId FROM issues i JOIN projects p ON p.id=i.project_id WHERE i.id=?").get(externalIssueMap.get(issue.id))})),
    warnings:['Attachment blobs, sprint history, subscriptions and notification state are not part of this project transfer.','Original issue numbers, board ranks, content and timestamps are retained; all included entity IDs are regenerated.']}};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {csvCell,csvChunks,jsonChunks} from '../src/modules/insight/transfer-export.js';
import {validateDocument} from '../src/modules/insight/transfer-validation.js';
import {insightScenario} from './insight-helpers.js';
async function bundle(s) {
  const label=(await s.api('POST','/projects/'+s.project.id+'/labels',{name:'Transfer label',color:'#123abc'})).data.label;
  const parent=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Parent'})).data.issue;
  await s.api('PATCH','/issues/'+s.issue.id,{parentId:parent.id,labelIds:[label.id],dueDate:'2028-02-29',description:'Quoted "text"\nMultiline body'});
  await s.member('POST','/issues/'+s.issue.id+'/comments',{body:'Transfer **comment**'});
  await s.api('POST','/issues/'+s.issue.id+'/relations',{targetIssueId:parent.id,kind:'relates'});
  return (await s.api('GET','/projects/'+s.project.id+'/export')).data;
}
test('JSON export streams a complete parseable document through canonical work readers',()=>insightScenario(async s=>{
  const document=await bundle(s);assert.equal(document.format,'crew.project');assert.equal(document.version,1);
  assert.equal(document.issues.length,2);assert.equal(document.comments[0].body,'Transfer **comment**');assert.equal(document.labels[0].name,'Transfer label');assert.equal(document.relations[0].kind,'relates');
  assert.deepEqual(JSON.parse([...jsonChunks(document)].join('')),document);assert.equal(validateDocument(document).issues.length,2);
}));
test('validated preview creates no project event index notification or activity state',()=>insightScenario(async s=>{
  const document=await bundle(s),before=s.server.ctx.db.prepare('SELECT count(*) n FROM projects').get().n;
  const events=[];const off=s.server.ctx.bus.subscribe(event=>events.push(event));
  try{const response=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'COPY',preview:true});assert.equal(response.status,200);assert.equal(response.data.preview.counts.issues,2);assert.equal(s.server.ctx.db.prepare('SELECT count(*) n FROM projects').get().n,before);assert.deepEqual(events,[]);}
  finally{off();}
}));
test('atomic JSON roundtrip preserves fields parent comments labels relations authors and timestamps with new IDs',()=>insightScenario(async s=>{
  const document=await bundle(s),result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'COPY',name:'Imported copy'});
  assert.equal(result.status,201,JSON.stringify(result.data));const imported=result.data;
  const again=(await s.api('GET','/projects/'+imported.project.id+'/export')).data;
  assert.equal(again.issues.length,document.issues.length);assert.equal(again.comments.length,document.comments.length);assert.equal(again.relations.length,document.relations.length);
  for(const source of document.issues){const id=imported.mappings.issues[source.id],item=again.issues.find(issue=>issue.id===id);assert.notEqual(id,source.id);for(const key of ['number','title','description','priority','assigneeId','estimate','dueDate','createdBy','rank','createdAt','updatedAt'])assert.equal(item[key],source[key],key);assert.equal(item.parentId,source.parentId?imported.mappings.issues[source.parentId]:null);assert.deepEqual(item.labelIds,source.labelIds.map(id=>imported.mappings.labels[id]));}
  assert.equal(again.comments[0].authorId,document.comments[0].authorId);assert.equal(again.comments[0].createdAt,document.comments[0].createdAt);
  const search=(await s.api('GET','/search?orgId='+s.org.id+'&q=project:COPY')).data;assert.equal(search.total,2);
}));
test('number gaps reverse order and child-before-parent imports preserve numbering and next counter',()=>insightScenario(async s=>{
  await s.api('DELETE','/issues/'+s.issue.id);
  const parent=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Number two'})).data.issue;
  const child=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Number three',parentId:parent.id})).data.issue;
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;document.issues.reverse();
  assert.deepEqual(document.issues.map(issue=>issue.number),[3,2]);
  const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'GAP'});assert.equal(result.status,201,JSON.stringify(result.data));
  const newIssue=(await s.api('POST','/projects/'+result.data.project.id+'/issues',{title:'Next after gap'})).data.issue;assert.equal(newIssue.number,4);
  const importedChild=(await s.api('GET','/issues/'+result.data.mappings.issues[child.id])).data.issue;assert.equal(importedChild.parentId,result.data.mappings.issues[parent.id]);
}));
test('missing references invalid timestamps and duplicate numbers yield useful errors before writes',()=>insightScenario(async s=>{
  const original=await bundle(s);
  const attempts=[document=>document.issues[0].labelIds.push('foreign'),document=>document.issues[0].statusId='foreign',document=>document.issues[0].updatedAt='bad',document=>document.issues[1].number=document.issues[0].number];
  for(const change of attempts){const document=structuredClone(original);change(document);const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'BAD'});assert.equal(result.status,422);assert(result.data.error.details);}
  assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='BAD'").get().n,0);
}));
test('parent and directed relation cycles are rejected with no partially imported project',()=>insightScenario(async s=>{
  const original=await bundle(s),parent=structuredClone(original);parent.issues[1].parentId=parent.issues[0].id;
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document:parent,key:'CYCLE'})).status,422);
  const graph=structuredClone(original);graph.relations[0].kind='blocks';graph.relations.push({...graph.relations[0],id:'reverse',sourceIssueId:graph.relations[0].targetIssueId,targetIssueId:graph.relations[0].sourceIssueId});
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document:graph,key:'CYCLE'})).status,422);
}));
test('write failure rolls back new project and suppresses all buffered public events and derived stores',()=>insightScenario(async s=>{
  const document=await bundle(s),tables=['projects','issues','comments','labels','issue_relations','activity','notifications','search_documents'];
  const census=()=>Object.fromEntries(tables.map(table=>[table,s.server.ctx.db.prepare('SELECT count(*) n FROM '+table).get().n]));
  const before=census(),events=[];const off=s.server.ctx.bus.subscribe(event=>events.push(event));
  s.server.ctx.db.exec("CREATE TEMP TRIGGER import_failure BEFORE INSERT ON comments BEGIN SELECT RAISE(ABORT,'controlled write failure'); END");
  try{const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'FAIL'});assert.equal(result.status,500);assert.deepEqual(census(),before);assert.deepEqual(events,[]);}
  finally{off();s.server.ctx.db.exec('DROP TRIGGER import_failure');}
}));
test('external relation endpoints require explicit writable same-organization mappings',()=>insightScenario(async s=>{
  const other=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'EXT',name:'External'})).data.project;
  const external=(await s.api('POST','/projects/'+other.id+'/issues',{title:'External target'})).data.issue;
  await s.api('POST','/issues/'+s.issue.id+'/relations',{targetIssueId:external.id,kind:'blocks'});
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;assert.equal(document.externalIssues[0].id,external.id);
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'LINK'})).status,422);
  const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'LINK',externalIssueMap:{[external.id]:external.id}});assert.equal(result.status,201,JSON.stringify(result.data));
  const relations=(await s.api('GET','/issues/'+result.data.mappings.issues[s.issue.id]+'/relations')).data.items;assert.equal(relations[0].relatedIssue.id,external.id);
}));
test('import mappings reject foreign user IDs and explicit member remapping updates authors and assignees',()=>insightScenario(async s=>{
  const document=await bundle(s);
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'MAP',userMap:{[s.memberUser.id]:'foreign'}})).status,422);
  const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'MAP',userMap:{[s.memberUser.id]:s.user.id}});assert.equal(result.status,201,JSON.stringify(result.data));
  const issue=(await s.api('GET','/issues/'+result.data.mappings.issues[s.issue.id])).data.issue;assert.equal(issue.assigneeId,s.user.id);
  const comments=(await s.api('GET','/issues/'+issue.id+'/comments')).data.items;assert.equal(comments[0].authorId,s.user.id);
}));
test('transfer permissions enforce scopes and organization project creation authority',()=>insightScenario(async s=>{
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;
  assert.equal((await s.member('POST','/orgs/'+s.org.id+'/import',{document,key:'NO'})).status,403);
  const token=(await s.api('POST','/tokens',{name:'Read only',scopes:['project:read']})).data.token;
  assert.equal((await s.api('GET','/projects/'+s.project.id+'/export',undefined,{Authorization:'Bearer '+token})).status,403);
}));
test('CSV escaping preserves quoted multiline cells and blocks whitespace-prefixed spreadsheet formulas',()=>{
  assert.equal(csvCell('a,"b"\nnext'),'"a,""b""\nnext"');
  for(const value of ['=SUM(A1)','+cmd','-cmd','@eval','  =hidden','\t+hidden'])assert.equal(csvCell(value),String.fromCharCode(34,39)+value+String.fromCharCode(34));
});

test('import rejects impossible UTC calendar days nonUTC metadata and invalid export dates',()=>insightScenario(async s=>{
  const original=await bundle(s);
  for(const mutate of [document=>document.issues[0].createdAt='2026-02-30T00:00:00.000Z',document=>document.issues[0].updatedAt='2026-10-16T08:00:00+00:00',document=>document.exportedAt='2026-02-30T00:00:00.000Z']){
    const document=structuredClone(original);mutate(document);const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'BADDATE'});assert.equal(result.status,422);assert.match(JSON.stringify(result.data.error.details),/UTC/);
  }
  assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='BADDATE'").get().n,0);
}));
